    return tasks", "new_text": "async def list_tasks(status: Optional[str] = None, priority: Optional[int] = None, assigned_to: Optional[str] = None, page: int = 1, page_size: int = 20):
    filtered_tasks = tasks

    # Filter by status
    if status:
        filtered_tasks = [task for task in filtered_tasks if task.status == status]

    # Filter by priority
    if priority:
        filtered_tasks = [task for task in filtered_tasks if task.priority == priority]

    # Filter by assigned_to
    if assigned_to:
        filtered_tasks = [task for task in filtered_tasks if task.assigned_to == assigned_to]

    # Pagination
    start = (page - 1) * page_size
    end = start + page_size
    return filtered_tasks[start:end]"}

